1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * The single derived identity used for owner duplicate detection.
12	 *
13	 * <p>An owner's {@code identityKey} is the lower-case SHA-256 hex digest (64 characters) of
14	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, computed from the owner's
15	 * already-normalized stored fields: the E.164 telephone (see {@link NormalizeOwnerTelephone}), the
16	 * lower-cased email (see {@link NormalizeOwnerEmail}), and the {@link Soundex} code of the last name.
17	 * Two owners are duplicates only when their whole keys are equal — consolidating what were once
18	 * separate telephone, email and household checks into this one comparison. Because the telephone is
19	 * part of the key, two owners with the same last name and postcode but different telephones have
20	 * different keys and are both allowed (the second is a {@link AssignPossibleDuplicate soft match}).
21	 */
22	public final class OwnerIdentityKey {
23	
24	    private OwnerIdentityKey() {
25	    }
26	
27	    /**
28	     * The identity key for an owner: SHA-256 hex over its stored (normalized) telephone, lower-cased
29	     * email and the Soundex of its last name.
30	     */
31	    public static String of(Owner owner) {
32	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
33	        String email = (owner.getEmail() == null || owner.getEmail().isBlank())
34	                ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
35	        String lastNameSoundex = Soundex.of(owner.getLastName());
36	        return sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
37	    }
38	
39	    /** The lower-case SHA-256 hex digest (64 characters) of {@code value}. */
40	    private static String sha256Hex(String value) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                    .digest(value.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(digest.length * 2);
45	            for (byte b : digest) {
46	                sb.append(String.format("%02x", b));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException("SHA-256 unavailable", e);
52	        }
53	    }
54	}
