1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
13	 * {@code normalizedLastName + '|' + postcode}. The household is therefore keyed on
14	 * (last name, postcode) alone, so any two owners with the same last name and postcode share the same
15	 * id automatically — nothing has to opt in and no existing owner is mutated. The {@code householdId}
16	 * is no longer part of {@link OwnerIdentityKey duplicate detection} (which is now the single identity
17	 * key); it still groups household members for the household-size count and membership rules. Runs on
18	 * the create pipeline before {@link SaveOwner}, so the stored id and the household-size count read the
19	 * same computed value.
20	 */
21	public class AssignHousehold {
22	
23	    public void service(@Val Owner owner) {
24	        String lastName = normalizeName(owner.getLastName());
25	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
26	        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
27	    }
28	
29	    /** The first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. */
30	    private static String deriveHouseholdId(String lastName, String postcode) {
31	        try {
32	            byte[] digest = MessageDigest.getInstance("SHA-256")
33	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
34	            StringBuilder sb = new StringBuilder();
35	            for (int i = 0; i < 6; i++) {
36	                sb.append(String.format("%02x", digest[i]));
37	            }
38	            return sb.toString();
39	        }
40	        catch (NoSuchAlgorithmException e) {
41	            throw new IllegalStateException("SHA-256 unavailable", e);
42	        }
43	    }
44	
45	    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
46	    private static String normalizeName(String value) {
47	        if (value == null) {
48	            return "";
49	        }
50	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
51	    }
52	}
