1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
13	import org.springframework.samples.petclinic.rest.function.common.Localities;
14	
15	/**
16	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where
17	 * REGION is the region derived from the owner's postcode (falling back to the city table), FY is the
18	 * two-digit fiscal year (starting 1 July) of the business-day-adjusted {@code registrationDate},
19	 * HASH8 is the first eight upper-case hex characters of SHA-256 over the normalized telephone
20	 * concatenated with the last name, and CHK is a single Luhn check digit computed over the digits of
21	 * {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D7}). Runs after telephone normalization and
22	 * the registration date default, so the hash is taken over the stored, normalized (E.164) telephone
23	 * and the fiscal year is known.
24	 *
25	 * <p>If the computed memberId collides with an existing owner's {@code memberId}, {@code -<n>} is
26	 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
27	 * receive distinct member ids. Runs before the owner is saved, so it is matched only against owners
28	 * already present.
29	 */
30	public class AssignMemberId {
31	
32	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
33	        String region = Localities.region(owner.getPostcode(), owner.getCity());
34	        String fy = String.format("%02d", FiscalYear.endingYear(owner.getRegistrationDate()) % 100);
35	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
36	        String core = region + fy + hash8;
37	        String base = core + luhn(core);
38	
39	        Set<String> existing = new HashSet<>();
40	        for (Owner other : ownerRepository.findAll()) {
41	            existing.add(other.getMemberId());
42	        }
43	
44	        String memberId = base;
45	        for (int n = 2; existing.contains(memberId); n++) {
46	            memberId = base + "-" + n;
47	        }
48	        owner.setMemberId(memberId);
49	    }
50	
51	    /**
52	     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
53	     * characters (the region letters and hex letters) are ignored; the digits are processed
54	     * right-to-left, doubling every second digit starting with the rightmost and subtracting 9 from
55	     * any doubled value above 9; the check digit is {@code (10 - (sum % 10)) % 10}.
56	     */
57	    private static int luhn(String value) {
58	        int sum = 0;
59	        boolean dbl = true;
60	        for (int i = value.length() - 1; i >= 0; i--) {
61	            char c = value.charAt(i);
62	            if (c < '0' || c > '9') {
63	                continue;
64	            }
65	            int d = c - '0';
66	            if (dbl) {
67	                d *= 2;
68	                if (d > 9) {
69	                    d -= 9;
70	                }
71	            }
72	            sum += d;
73	            dbl = !dbl;
74	        }
75	        return (10 - (sum % 10)) % 10;
76	    }
77	
78	    /** First {@code length} upper-case hex characters of SHA-256({@code value}). */
79	    private static String shaHex(String value, int length) {
80	        return sha256hex(value).substring(0, length).toUpperCase();
81	    }
82	
83	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
84	    private static String sha256hex(String value) {
85	        try {
86	            byte[] digest = MessageDigest.getInstance("SHA-256")
87	                    .digest(value.getBytes(StandardCharsets.UTF_8));
88	            StringBuilder sb = new StringBuilder(digest.length * 2);
89	            for (byte b : digest) {
90	                sb.append(String.format("%02x", b));
91	            }
92	            return sb.toString();
93	        }
94	        catch (NoSuchAlgorithmException e) {
95	            throw new IllegalStateException("SHA-256 not available", e);
96	        }
97	    }
98	}
