1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The American Soundex encoding of a surname: a four-character phonetic code (an initial letter
5	 * followed by three digits) that maps similarly-sounding names to the same value. Used by the owner
6	 * {@link OwnerIdentityKey identity key} and by the {@link AssignPossibleDuplicate soft-match} so that
7	 * spelling variants of one surname are treated as the same household name.
8	 *
9	 * <p>A null, blank or letter-free name encodes to the empty string.
10	 */
11	public final class Soundex {
12	
13	    private Soundex() {
14	    }
15	
16	    /** The four-character American Soundex code for {@code name}, or {@code ""} when it has no letters. */
17	    public static String of(String name) {
18	        if (name == null) {
19	            return "";
20	        }
21	        StringBuilder letters = new StringBuilder();
22	        for (int i = 0; i < name.length(); i++) {
23	            char c = name.charAt(i);
24	            if (Character.isLetter(c)) {
25	                letters.append(Character.toUpperCase(c));
26	            }
27	        }
28	        if (letters.length() == 0) {
29	            return "";
30	        }
31	        StringBuilder code = new StringBuilder();
32	        char first = letters.charAt(0);
33	        code.append(first);
34	        char prev = digit(first);
35	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
36	            char c = letters.charAt(i);
37	            char d = digit(c);
38	            if (d != '0' && d != prev) {
39	                code.append(d);
40	            }
41	            // 'H' and 'W' are transparent: they do not reset the previous code, so two like-coded
42	            // consonants they separate still collapse to one. A vowel resets it, so they code twice.
43	            if (c != 'H' && c != 'W') {
44	                prev = d;
45	            }
46	        }
47	        while (code.length() < 4) {
48	            code.append('0');
49	        }
50	        return code.toString();
51	    }
52	
53	    private static char digit(char c) {
54	        switch (c) {
55	            case 'B': case 'F': case 'P': case 'V':
56	                return '1';
57	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
58	                return '2';
59	            case 'D': case 'T':
60	                return '3';
61	            case 'L':
62	                return '4';
63	            case 'M': case 'N':
64	                return '5';
65	            case 'R':
66	                return '6';
67	            default: // A, E, I, O, U, Y, H, W
68	                return '0';
69	        }
70	    }
71	}
