1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.net.URI;
4	import java.util.concurrent.atomic.AtomicLong;
5	
6	import net.officefloor.plugin.variable.Val;
7	import net.officefloor.web.ObjectResponse;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	import org.springframework.http.ResponseEntity;
11	import org.springframework.samples.petclinic.mapper.OwnerMapper;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	
15	public class RespondWithOwnerCreated {
16	
17	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
18	
19	    /** Monotonically increasing sequence stamped on every OWNER_CREATED event across all creates. */
20	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
21	
22	    public void service(@Val Owner owner, OwnerMapper ownerMapper,
23	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
24	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
25	        auditLogger.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
26	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), dto.getMembershipLevel());
27	        auditLogger.info(ownerCreatedEvent(EVENT_SEQ.incrementAndGet(), owner, dto.getMembershipLevel()));
28	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
29	    }
30	
31	    /**
32	     * Renders the immutable structured OWNER_CREATED event. The {@code memberId} field carries the
33	     * owner's primary identifier, now that the customerCode and membershipNumber have been unified
34	     * into the memberId; {@link #primaryIdentifier(Owner)} is the single place that resolves it.
35	     */
36	    private static String ownerCreatedEvent(long seq, Owner owner, int membershipLevel) {
37	        return "{\"seq\":" + seq
38	                + ",\"ownerId\":" + owner.getId()
39	                + ",\"memberId\":" + jsonString(primaryIdentifier(owner))
40	                + ",\"membershipLevel\":" + membershipLevel
41	                + ",\"event\":\"OWNER_CREATED\"}";
42	    }
43	
44	    /** The owner's primary identifier: the unified memberId. */
45	    private static String primaryIdentifier(Owner owner) {
46	        return owner.getMemberId();
47	    }
48	
49	    /** Renders a string as a JSON literal (quoted, with the mandatory escapes), or {@code null}. */
50	    private static String jsonString(String value) {
51	        if (value == null) {
52	            return "null";
53	        }
54	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
55	        for (int i = 0; i < value.length(); i++) {
56	            char c = value.charAt(i);
57	            switch (c) {
58	                case '"' -> sb.append("\\\"");
59	                case '\\' -> sb.append("\\\\");
60	                case '\n' -> sb.append("\\n");
61	                case '\r' -> sb.append("\\r");
62	                case '\t' -> sb.append("\\t");
63	                default -> {
64	                    if (c < 0x20) {
65	                        sb.append(String.format("\\u%04x", (int) c));
66	                    }
67	                    else {
68	                        sb.append(c);
69	                    }
70	                }
71	            }
72	        }
73	        return sb.append('"').toString();
74	    }
75	}
