1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the size of the owner's household: the number of owners that share this owner's
9	 * {@code householdId}, counting the owner itself. An owner with no {@code householdId} is a
10	 * household of one. Household membership is assigned by {@link AssignHousehold}. Runs on both the
11	 * create and read pipelines so the count is derived consistently from current data.
12	 */
13	public class AssignHouseholdMemberCount {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String householdId = owner.getHouseholdId();
17	        if (householdId == null) {
18	            owner.setHouseholdMemberCount(1);
19	            return;
20	        }
21	        long count = ownerRepository.findAll().stream()
22	                .filter(existing -> householdId.equals(existing.getHouseholdId()))
23	                .count();
24	        owner.setHouseholdMemberCount((int) count);
25	    }
26	}
