1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
7	
8	/**
9	 * The duplicate check, rejecting a create-owner request with a {@link DuplicateOwnerException} (409)
10	 * on a single ground: the whole derived {@link OwnerIdentityKey} — the SHA-256 hex over
11	 * {@code telephone|lowerEmail|soundex(lastName)} — equals an existing owner's. Duplicate detection is
12	 * now this one identity key; the earlier separate household-duplicate ground (a shared computed
13	 * {@code householdId}) no longer applies, so two owners with the same last name and postcode but
14	 * different telephones have different keys and are both accepted (the second is flagged a soft match
15	 * by {@link AssignPossibleDuplicate}).
16	 *
17	 * <p>The email-domain blocklist is applied first, upstream, by {@link RejectDisposableEmailDomain}.
18	 * A soft-deleted owner is ignored. Runs after {@link BuildOwner} so the new owner's telephone, email
19	 * and last name are in their stored, normalized form, and before {@link SaveOwner} so the
20	 * not-yet-persisted new owner is compared only against existing owners.
21	 */
22	public class CheckOwnerIdentityUnique {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
25	            throws DuplicateOwnerException {
26	        String identityKey = OwnerIdentityKey.of(owner);
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
29	                continue; // never a duplicate of itself
30	            }
31	            if (Boolean.TRUE.equals(existing.getDeleted())) {
32	                continue; // a soft-deleted owner is ignored by the duplicate check
33	            }
34	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
35	                throw new DuplicateOwnerException(identityKey);
36	            }
37	        }
38	    }
39	}
