1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Raises the soft-match {@code possibleDuplicate} flag. A create request that is not a hard duplicate
12	 * (see {@link CheckOwnerIdentityUnique}) can still resemble an existing owner: when its
13	 * {@link OwnerIdentityKey identityKey} <em>differs</em> from an existing owner's but the two share a
14	 * last-name {@link Soundex} code and a postcode, the new owner is created with {@code possibleDuplicate}
15	 * true and {@code possibleDuplicateOf} set to the matching owner's id. Otherwise {@code possibleDuplicate}
16	 * is false and {@code possibleDuplicateOf} absent.
17	 *
18	 * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
19	 * but different telephones are no longer a hard duplicate — the second reaches this step and is flagged
20	 * here. A declared household member ({@code sharesHousehold}) is not a suspected duplicate and is never
21	 * flagged.
22	 *
23	 * <p>Runs after {@link BuildOwner} (telephone, last name and postcode are in their stored form) and
24	 * after {@link CheckOwnerIdentityUnique}, and before {@link SaveOwner} so the flag is compared only
25	 * against existing owners. When several existing owners match, the one with the lowest id wins for a
26	 * deterministic result.
27	 */
28	public class AssignPossibleDuplicate {
29	
30	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
31	        owner.setPossibleDuplicate(false);
32	        owner.setPossibleDuplicateOf(null);
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return; // a declared household member is not a suspected duplicate
35	        }
36	        String postcode = normalize(owner.getPostcode());
37	        if (postcode.isEmpty()) {
38	            return; // no postcode to match on
39	        }
40	        String soundex = Soundex.of(owner.getLastName());
41	        if (soundex.isEmpty()) {
42	            return; // no last name to match on
43	        }
44	        String identityKey = OwnerIdentityKey.of(owner);
45	        Owner match = null;
46	        for (Owner existing : ownerRepository.findAll()) {
47	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
48	                continue; // never a duplicate of itself
49	            }
50	            if (Boolean.TRUE.equals(existing.getDeleted())) {
51	                continue; // a soft-deleted owner is ignored by the soft-match check
52	            }
53	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
54	                continue; // an equal key is a hard duplicate, not a soft match (and never reaches here)
55	            }
56	            if (soundex.equals(Soundex.of(existing.getLastName()))
57	                    && postcode.equals(normalize(existing.getPostcode()))) {
58	                if (match == null || existing.getId() < match.getId()) {
59	                    match = existing;
60	                }
61	            }
62	        }
63	        if (match != null) {
64	            owner.setPossibleDuplicate(true);
65	            owner.setPossibleDuplicateOf(match.getId());
66	        }
67	    }
68	
69	    private static String normalize(String value) {
70	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
71	    }
72	}
