1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Derives an owner's locality (region). The postcode is preferred: when it falls within a known
8	 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) that region is returned.
9	 * Only when the postcode is absent or in no known range does the fixed city-to-region table apply.
10	 * Anything the postcode and city both fail to resolve derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class Localities {
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    /** Region -> IANA timezone name. */
27	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
28	            "NSW", "Australia/Sydney",
29	            "VIC", "Australia/Melbourne",
30	            "QLD", "Australia/Brisbane");
31	
32	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
33	
34	    /** Locality returned for any city not in the table. */
35	    public static final String UNKNOWN = "UNKNOWN";
36	
37	    private Localities() {
38	    }
39	
40	    /**
41	     * @param city the owner's city (may be {@code null}).
42	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is not
43	     *         in the table.
44	     */
45	    public static String region(String city) {
46	        return CITY_REGION.getOrDefault(city, UNKNOWN);
47	    }
48	
49	    /**
50	     * Derives the locality preferring the postcode over the city.
51	     *
52	     * @param postcode the owner's postcode (may be {@code null} or blank).
53	     * @param city     the owner's city (may be {@code null}).
54	     * @return the region for {@code postcode} when it falls in a known range; otherwise the
55	     *         city-derived region, or {@code "UNKNOWN"} when neither resolves.
56	     */
57	    public static String region(String postcode, String city) {
58	        String byPostcode = regionForPostcode(postcode);
59	        return byPostcode != null ? byPostcode : region(city);
60	    }
61	
62	    /**
63	     * Derives the IANA timezone name for an owner, from the region derived by
64	     * {@link #region(String, String)} via the fixed region-to-timezone table
65	     * (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane).
66	     *
67	     * @param postcode the owner's postcode (may be {@code null} or blank).
68	     * @param city     the owner's city (may be {@code null}).
69	     * @return the IANA timezone name, or {@code null} when the region is not in the table.
70	     */
71	    public static String timezone(String postcode, String city) {
72	        return REGION_TIMEZONE.get(region(postcode, city));
73	    }
74	
75	    /**
76	     * @return the region whose inclusive range contains {@code postcode}, or {@code null} when the
77	     *         postcode is absent, malformed, or in no known range.
78	     */
79	    private static String regionForPostcode(String postcode) {
80	        if (postcode == null || postcode.isBlank() || !FOUR_DIGITS.matcher(postcode).matches()) {
81	            return null;
82	        }
83	        int value = Integer.parseInt(postcode);
84	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
85	            int[] range = entry.getValue();
86	            if (value >= range[0] && value <= range[1]) {
87	                return entry.getKey();
88	            }
89	        }
90	        return null;
91	    }
92	}
